-- ============================================================
-- 078 · EZ2DJ : AZURE EXPRESSION INTEGRAL COMPOSITION 서열표 (채보만 · 투표 없음)
--
-- ─── 무엇을 만드는가 ─────────────────────────────────────
-- EZ2DJ 의 **마지막** 버전, 흔히 **AEIC** 로 부르는 것입니다.
-- 곡 231개 · 채보 **2,288개**. 투표는 넣지 않아 전부 '미정' 입니다.
--
-- ⚠ 다음 버전부터는 이름이 **EZ2AC** 로 바뀝니다. EZ2DJ 기종(machine_id = 10)에
--   버전을 더하는 것은 여기까지입니다.
--
-- ─── ⚠ 이 파일의 숫자는 AEIC 것이 아닙니다 ───────────────
-- **AEIC 수록곡 문서에는 곡 이름만 있고 난이도가 한 칸도 없습니다.**
-- 지금까지의 버전은 모두 (곡 × 모드 × 난이도) 표가 있었는데 이 문서만 한 줄짜리
-- 목록입니다. AEIC 본문서 · 삭제곡 문서에도 그 표는 없습니다.
--
--   곡 목록  ← 나무위키 『EZ2DJ : AZURE EXPRESSION INTEGRAL COMPOSITION/수록곡』
--              https://namu.wiki/w/EZ2DJ : AZURE EXPRESSION INTEGRAL COMPOSITION/수록곡
--              (235곡 · 이 파일이 넣는 곡의 명단은 전적으로 여기서 옵니다)
--
--   난이도   ← 나무위키 『EZ2AC : ENDLESS CIRCULATION/수록곡』 (**다음 버전**)
--              https://namu.wiki/w/EZ2AC : ENDLESS CIRCULATION/수록곡
--
-- 즉 **레벨은 전부 EC(EZ2AC 1세대) 기준값**입니다. AEIC 당시와 다를 수 있습니다.
-- 074(1.5)가 2.0 표를 빌린 것과 같은 처지인데, 이번엔 한 세대를 건너뜁니다.
-- AEIC 난이도표가 나오면 아래 3)의 표를 갈아 끼우면 됩니다.
--
-- ─── 난이도를 어디서 가져왔는지 (235곡의 내역) ───────────
--   224곡 — EC 표에 있는 곡. 그 줄의 값을 씁니다.
--     7곡 — EC 에서 삭제돼 줄이 없는 곡. **DB 의 BErA 채보를 그대로 이어받습니다**
--           (Bob · For 3 Weeks · Love & Extasy · Love & Extasy (Remix) · My Honey ·
--            Finite · Underflow — 64채보). AEIC 바로 앞 버전이라 가장 가깝습니다.
--     4곡 — **어디에도 없어 넣지 못했습니다.** AE 시절 리믹스 넷인데 EC 가 지웠고
--           DB 에도 없습니다: 20000000000 (Hurt Bass Remix) ·
--           Anemia (Synth Pop Remix) · Back to Bed (Crimson Red Remix) ·
--           I Do Love You (Insida Club Remix).
--           (모드, 레벨)이 없으면 서열표에 놓을 자리가 없어 곡도 넣지 않습니다 —
--           075 의 판단과 같습니다. 그래서 곡이 235 가 아니라 **231** 입니다.
--
-- ─── EC 표에서 두 칸을 버립니다 ──────────────────────────
-- EC 는 가로 22칸이고 BErA(077)는 20칸입니다. 늘어난 둘이 **Club SHD** 와
-- **Turn EZ** 인데, EC 에서 생긴 칸으로 보고 넣지 않습니다 (074 가 Ruby HD ·
-- 7Street SHD 를 버린 것과 같은 기준). 실제로 버려지는 값은 **두 칸뿐**이라
-- 표에 미치는 영향은 거의 없습니다.
--
-- 남는 20칸의 차례는 077 과 같습니다:
--   Ruby N·H │ 5Street E·N·H·S │ 7Street E·N·H·S │ Club E·N·H │ Space N·H
--   │ Catch E·N·H │ Turn N·H
--
-- ─── 한 칸에 숫자가 둘인 곳 ──────────────────────────────
-- DIEOXIN 의 Space HD 가 `10 14` 입니다 (077 에서와 같은 자리). 077 처럼 공백으로
-- 쪼개 **같은 칸의 채보 둘**로 넣습니다.
--
-- ─── 곡 이름 ─────────────────────────────────────────────
-- 두 문서가 같은 곡을 다르게 적어서 이름을 두 번 맞춥니다.
--
--   ① AEIC 표기 → EC 표기 : 아래 3)의 곡명은 **AEIC 문서 표기가 아니라 DB 표기**
--      입니다. 생성할 때 EC 쪽 이름으로 찾아가 값을 읽었습니다. EC 는 부제를
--      `- Subtitle -` 로 적고(`The Future - Access -`), 오타를 그대로 둔 채
--      `[오타]` 를 달아 둔 줄이 넷 있습니다 — Speical K · Don't say anyting ·
--      if I coudn't see you again · JMJ - DMC Space Gear Re-Formation -.
--      AEIC 쪽 이름으로 이어 붙였습니다.
--
--   ② AEIC 표기 → DB 표기 : 아래 2)의 별칭 12줄입니다.
--
-- ⚠ AEIC 문서에도 오타가 있습니다 — `J.M.J (DFC Space Gear Re-formation` 는
--   닫는 괄호가 없습니다. 글자를 정규화하면 이미 있는 곡과 붙어 그대로 씁니다.
--
-- ─── 새로 들어오는 곡 32개 ───────────────────────────────
-- AE(AZURE EXPRESSION) 구간 16곡 — 1950 · AXIS · Core · Frostbite · Intuition ·
--   Illusion · if I couldn't see you again · Liquid Cube · Morgenglut 2012 ·
--   Nihilism · Rising In My Heart · satellite 61 · The Ashtray ·
--   The Greatest Escape · The Onyx Night Sky · Taillight Phantom
-- AEIC 구간 10곡 — Andes · Crisp · Disease · Extra Wave · Frozen Eyes ·
--   Nachthexen · Out of the Blue · Phat Trash · Resonance Spectra · Wind Tales
-- 앞 버전에서 줄이 없어 못 넣었던 둘 — Dance with me (Dischord Edit) ·
--   Refresh (J-Style Edit) (2.0 신곡인데 그때는 원곡 하드믹스에 흡수돼 있었습니다)
-- 그리고 AE 리믹스 넷은 위에 적은 대로 빠집니다.
--
-- ─── 난이도 상한은 18 ────────────────────────────────────
-- 076 에서 18 로 오른 뒤 그대로입니다.
--
-- ─── 여러 번 실행해도 결과가 같습니다 ────────────────────
-- 행은 전부 ON CONFLICT DO NOTHING. 쪼갠 뒤에도 (곡, 모드, 난이도, 레벨)이
-- 완전히 같은 줄은 없는 것을 확인했습니다.
--
-- 되돌리려면: MIGRATION_FILES 에서 빼고 schema_migrations 에서 지운 뒤
--   DELETE FROM charts WHERE version_id =
--     (SELECT id FROM game_versions WHERE machine_id = 10 AND code = 'AEIC');
--   DELETE FROM game_versions WHERE machine_id = 10 AND code = 'AEIC';
--   DELETE FROM songs WHERE machine_id = 10 AND id NOT IN (SELECT song_id FROM charts);
-- ============================================================

-- ─── 1) AEIC ──────────────────────────────────────────────
ON CONFLICT DO NOTHING;

-- ─── 2) 곡 이름 별칭 (AEIC 표기 → 이미 있는 이름) ─────────
-- 아래 3)·6)의 곡명은 이 별칭을 **이미 적용한 뒤**의 DB 표기입니다. 이 표는
-- 무엇을 무엇에 붙였는지 남겨 두려고 싣습니다 (SQL 이 쓰지는 않습니다).
--
--   Confete (Evening Mix)        → Confete ~ Remix ~
--   Stay (Radio Edit Mix)        → Stay ~ Radio Edit ~
--   Judgement                    → Judgment
--   Metagalactic G-1000          → Metagalactic
--   One Two Three Four           → 1234
--   Theme of EZ2DJ 2             → Ez2Dj (찬가 II)
--   Be My Baby (Funky Version)   → Be My Baby Funky Mix
--   JAM (A.C Version)            → Jam A.C. Ver.
--   Look Out (EK-1 Beat Version) → Look Out EK1-Beat Ver.
--   The Boy (EK-2 Beat Version)  → The Boy EK2-Beat Ver.
--   With your Girl (Beach Ver.)  → With you Girl Beach Ver.
--   Dance Machine (YK House Edit)→ Dance Machine (YK Edit)

-- ─── 3) EC 표에서 빌려 온 난이도 (224곡 × 20칸) ───────────
-- 곡 차례는 AEIC 문서의 차례 그대로입니다. 값은 EC 문서의 같은 곡 줄에서
-- Club SHD · Turn EZ 두 칸을 뺀 것입니다.
CREATE TEMP TABLE ez2dj_aeic (
  title TEXT,
  ruby_n TEXT, ruby_h TEXT,
  s5e TEXT, s5n TEXT, s5h TEXT, s5s TEXT,
  s7e TEXT, s7n TEXT, s7h TEXT, s7s TEXT,
  club_e TEXT, club_n TEXT, club_h TEXT,
  sp_n TEXT, sp_h TEXT,
  cat_e TEXT, cat_n TEXT, cat_h TEXT,
  turn_n TEXT, turn_h TEXT
);


-- ─── 4) EC 에 줄이 없어 BErA 에서 이어받는 7곡 ────────────
CREATE TEMP TABLE ez2dj_aeic_carry (title TEXT);


-- ─── 5) 곡 (새로 들어오는 32곡만 늘어납니다) ──────────────
SELECT DISTINCT 10, title, NULL FROM (
  SELECT title FROM ez2dj_aeic
  UNION ALL
  SELECT title FROM ez2dj_aeic_carry
) t
ON CONFLICT DO NOTHING;

-- ─── 6) 채보 ① EC 에서 빌려 온 2,224개 ────────────────────
CREATE TEMP TABLE ez2dj_aeic_charts AS
SELECT t.title,
       v.mode,
       v.difficulty,
       CASE WHEN x.one IN ('?', '☠') THEN NULL ELSE x.one::int END AS level
FROM ez2dj_aeic t
CROSS JOIN LATERAL (VALUES
  ('RUBY',  'NM',  t.ruby_n),
  ('RUBY',  'HD',  t.ruby_h),
  ('5ST',   'EZ',  t.s5e),
  ('5ST',   'NM',  t.s5n),
  ('5ST',   'HD',  t.s5h),
  ('5ST',   'SHD', t.s5s),
  ('7ST',   'EZ',  t.s7e),
  ('7ST',   'NM',  t.s7n),
  ('7ST',   'HD',  t.s7h),
  ('7ST',   'SHD', t.s7s),
  ('CLUB',  'EZ',  t.club_e),
  ('CLUB',  'NM',  t.club_n),
  ('CLUB',  'HD',  t.club_h),
  ('SPACE', 'NM',  t.sp_n),
  ('SPACE', 'HD',  t.sp_h),
  ('CATCH', 'EZ',  t.cat_e),
  ('CATCH', 'NM',  t.cat_n),
  ('CATCH', 'HD',  t.cat_h),
  ('TURN',  'NM',  t.turn_n),
  ('TURN',  'HD',  t.turn_h)
) AS v(mode, difficulty, val)
CROSS JOIN LATERAL unnest(string_to_array(v.val, ' ')) AS x(one)
WHERE v.val NOT IN ('X', '-', '');

DO $mig$
DECLARE
  has_label BOOLEAN := EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'charts' AND column_name = 'level_label'
  );
BEGIN
  EXECUTE format($q$
    SELECT s.id, gv.id, e.mode, e.difficulty, e.level%s
    FROM ez2dj_aeic_charts e
    JOIN songs s          ON s.machine_id  = 10 AND s.title = e.title
    JOIN game_versions gv ON gv.machine_id = 10 AND gv.code = 'AEIC'
    ON CONFLICT DO NOTHING
  $q$,
    CASE WHEN has_label THEN ', level_label'                    ELSE '' END,
    CASE WHEN has_label THEN ', COALESCE(e.level::text, ''?'')' ELSE '' END);

  -- ── 채보 ② BErA 에서 그대로 이어받는 64개 ──
  -- level_label 은 새로 짜지 않고 복사합니다 (074 의 2) 와 같은 이유 — level 이
  -- NUMERIC 이라 ::text 로 만들면 `5.00` 이 되어 레벨 칸이 둘로 쪼개집니다).
  EXECUTE format($q$
    SELECT c.song_id, dst.id, c.mode, c.difficulty, c.level%s
    FROM charts c
    JOIN songs s            ON s.id  = c.song_id AND s.machine_id = 10
    JOIN game_versions src  ON src.id = c.version_id
                           AND src.machine_id = 10 AND src.code = '7thBErA'
    JOIN game_versions dst  ON dst.machine_id = 10 AND dst.code = 'AEIC'
    WHERE s.title IN (SELECT title FROM ez2dj_aeic_carry)
    ON CONFLICT DO NOTHING
  $q$,
    CASE WHEN has_label THEN ', level_label'   ELSE '' END,
    CASE WHEN has_label THEN ', c.level_label' ELSE '' END);
END
$mig$;

DROP TABLE ez2dj_aeic_charts;
DROP TABLE ez2dj_aeic_carry;
DROP TABLE ez2dj_aeic;

-- ─── 7) 집계 캐시 초기화 ──────────────────────────────────
SELECT recalc_chart_stats(c.id)
FROM charts c JOIN songs s ON s.id = c.song_id
WHERE s.machine_id = 10;
